// Exact authored native-PKG helper strings. No generated-language writes.
const LANGS=['es','pt','fr','de','ru','tr','pl','it','zh','ja','ko','th','vi','id','hi','sr','nl','ka','ar','he'];
const table={};
function row(key,text){const cells=text.split('|'),tokens=(key.match(/\{\w+\}/g)||[]).sort().join(',');if(cells.length!==LANGS.length||cells.some(x=>!x.trim()))throw Error('Invalid package-installer translation row: '+key);table[key]=Object.fromEntries(LANGS.map((code,i)=>{if((cells[i].match(/\{\w+\}/g)||[]).sort().join(',')!==tokens)throw Error('Package-installer placeholder mismatch: '+key);return[code,cells[i]];}));}

